// Synthetic simulation of GapMap's verifier. Uses the REAL engine code (verify.js + engine.js LIBRARY).
// No AI is called. The student answers are generated by code, so this tests the verifier logic, not handwriting reading.
const v = require('./verify');
const { LIBRARY, findLibraryRule, numbersOf } = require('./services/engine');
const { create, all } = require('mathjs');
const math = create(all, { number: 'Fraction' });
function rng(seed){return function(){seed|=0;seed=(seed+0x6D2B79F5)|0;let t=Math.imul(seed^(seed>>>15),1|seed);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
const rnd = rng(20261121);
const ri = (a,b)=>a+Math.floor(rnd()*(b-a+1));
const pf = ()=>{const d=ri(2,9);return [ri(1,d-1),d];};
const ruleOf = (name)=>LIBRARY.find(r=>r.name===name).rule;
function fracQ(op){ // proper fractions; for '-' make the first one larger
  let [a,b]=pf(),[c,d]=pf();
  if(op==='-'){ while(a/b<=c/d){[a,b]=pf();[c,d]=pf();} }
  return `${a}/${b}${op}${c}/${d}`;
}
function intQ(kind){ const a=ri(1,9),b=ri(1,9); return kind==='neg'?`${a}-(-${b})`:`-${a}+${b}`; }
function evalRule(rule,expr){ // student answer produced by following a rule, or null if undefined
  try{ const s={}; numbersOf(expr).forEach((x,i)=>s['n'+(i+1)]=math.fraction(x)); return math.fraction(math.evaluate(rule,s)); }catch(e){return null;}
}
const fmt=(f)=>f.toFraction();
// which question type each library slip belongs to
const SLIPS=[
 ['Adds tops and bottoms of fractions','+'],['Subtracts tops and bottoms of fractions','-'],
 ['Adds the tops and keeps the first bottom','+'],['Subtracts the tops and keeps the first bottom','-'],
 ['Flips the second fraction when multiplying','*'],['Multiplies the tops but adds the bottoms','*'],
 ['Adds the tops but multiplies the bottoms','+'],
 ['Ignores the minus sign inside brackets','neg'],['Adds the numbers and keeps a minus sign','pos'] ];
const mkQ=(t)=> t==='neg'?intQ('neg'): t==='pos'?intQ('pos'): fracQ(t);
const N=10000;
const MODE=process.env.MODE||'patched';
function match(q,a){
  if(MODE==='original'){ // the library matcher as it was before the patch: first slip that reproduces the answer, any question type
    for(const r of LIBRARY){ if(v.verifyRule(r.rule,numbersOf(q),a).verified) return {...r}; } return null; }
  return findLibraryRule({expression:q},a); // patched engine: own question type only, exactly one slip may match
}
// ---- A. item level: student follows a real slip
const A=[]; let tot={ok:0,other:0,none:0,n:0};
for(const [name,t] of SLIPS){
  const rule=ruleOf(name); let ok=0,other=0,none=0,n=0;
  while(n<N){ const q=mkQ(t); const ans=evalRule(rule,q); if(!ans) continue; const c=v.computeCorrect(q); if(math.equal(ans,c)) continue;
    n++; const hit=match(q,fmt(ans));
    if(!hit) none++; else if(hit.name===name) ok++; else other++; }
  A.push({name,ok,other,none,n}); tot.ok+=ok;tot.other+=other;tot.none+=none;tot.n+=n;
}
// ---- B. item level: wrong answers that are NOT a library slip (should get no label)
function careless(q,kind){
  const c=v.computeCorrect(q);
  if(kind==='num'){ const f=math.fraction(c); const d=f.d, nn=f.n*f.s+(rnd()<0.5?1:-1); return fmt(math.fraction(nn,d)); }
  if(kind==='lcd'){ const m=q.match(/(\d+)\/(\d+)([+\-*])(\d+)\/(\d+)/); const [a,b,op,cc,d]=[+m[1],+m[2],m[3],+m[4],+m[5]];
    const top=op==='+'?a*d+cc*b:op==='-'?a*d-cc*b:a*cc; const bot=op==='*'?b*d:b*d; return fmt(math.fraction(top+(rnd()<0.5?1:-1),bot)); }
  const d=ri(2,12); return fmt(math.fraction(ri(1,d),d)); // random fraction
}
const B={};
for(const kind of ['num','lcd','rand']){
  let flagged=0,n=0;
  while(n<N){ const op=['+','-','*'][ri(0,2)]; const q=fracQ(op); let a; try{a=careless(q,kind);}catch(e){continue;}
    const r=v.checkAnswer(q,a); if(r.status!=='wrong') continue; n++; if(match(q,a)) flagged++; }
  B[kind]={flagged,n};
}
// ---- C. student level (7-question test: 3 add, 2 subtract, 2 multiply), as the app does
function runStudent(answerFn){
  const ops=['+','+','+','-','-','*','*']; const items=[];
  ops.forEach((op,i)=>{ const q=fracQ(op); const a=answerFn(q,op); const r=v.checkAnswer(q,a);
    if(r.status==='correct') items.push({q:i+1,status:'correct'});
    else { const hit=match(q,a); items.push({q:i+1,status:'wrong',verified:!!hit,ruleExpression:hit&&hit.rule}); } });
  return v.summarizeStudent(items);
}
const FAM=[['Adds tops and bottoms of fractions','+'],['Subtracts tops and bottoms of fractions','-'],['Flips the second fraction when multiplying','*'],['Multiplies the tops but adds the bottoms','*']];
const C=[];
for(const [name,op] of FAM){
  let likely=0,susp=0,none=0,wrongLabel=0; const M=N/2;
  for(let i=0;i<M;i++){ const rule=ruleOf(name);
    const s=runStudent((q,o)=>{ if(o===op && rnd()<0.8){ const a=evalRule(rule,q); if(a) return fmt(a);} return fmt(v.computeCorrect(q)); });
    const f=s.findings.find(x=>x.signature===rule.replace(/\s+/g,''));
    if(f&&f.level==='likely') likely++; else if(f) susp++; else none++;
    if(s.findings.some(x=>x.signature!==rule.replace(/\s+/g,''))) wrongLabel++; }
  C.push({name,likely,susp,none,wrongLabel,M});
}
let fl=0,fs=0,fa=0; const M2=N;
for(let i=0;i<M2;i++){
  const s=runStudent((q)=>{ if(rnd()<0.3){ return careless(q,['num','lcd','rand'][ri(0,2)]); } return fmt(v.computeCorrect(q)); });
  if(s.findings.length) fa++; if(s.findings.some(f=>f.level==='likely')) fl++; if(s.findings.some(f=>f.level==='suspected')) fs++; }
const out={A,tot,B,C,careless:{students:M2,anyLabel:fa,likely:fl,suspected:fs}};
console.log(JSON.stringify(out,null,1));
require('fs').writeFileSync(__dirname+'/sim-result-'+MODE+'.json',JSON.stringify(out,null,1));
